template:
[# OVN Interconnection Database (ovn-ic-db) configuration
# Global database options
[Global]
  # Database engine type (e.g., "external")
  {{- "backend" }} = {{ global_backend }}

  # Maximum number of connections allowed (0 = unlimited)
  {{- "max_connections" }} = {{ global_max_connections }}

  # Path to SSL certificate for secure connections
  {{- "ssl_cert" }} = {{ global_ssl_cert | default('') }}

  # Path to SSL private key
  {{- "ssl_private_key" }} = {{ global_ssl_private_key | default('') }}

  # Path to CA certificate for verifying client certs
  {{- "ssl_ca_cert" }} = {{ global_ssl_ca_cert | default('') }}

  # Enable SSL/TLS for external connections
  {{- "use_ssl" }} = {{ global_use_ssl | default(false) | lower }}

  # Optional cluster ID for multi-site deployments
  {{- "cluster_id" }} = {{ global_cluster_id | default('') }}

# OVN IC DB specific settings
[ovn-ic-db]
  # Enable interconnection database mode
  {{- "enable" }} = {{ ic_enable | default(true) | lower }}

  # Name of this site/cluster (must be unique across interconnection)
  {{- "site_id" }} = {{ ic_site_id }}

  # List of peer site IDs and connection details
{% for peer in ic_peers %}
  # Peer site: {{ peer.site_id }}
  {{- "peer_" }}{{ peer.site_id }}{{ "_url" }} = {{ peer.url }}
  {{- "peer_" }}{{ peer.site_id }}{{ "_ssl_cert" }} = {{ peer.ssl_cert | default('') }}
  {{- "peer_" }}{{ peer.site_id }}{{ "_ssl_private_key" }} = {{ peer.ssl_private_key | default('') }}
  {{- "peer_" }}{{ peer.site_id }}{{ "_ssl_ca_cert" }} = {{ peer.ssl_ca_cert | default('') }}
{% endfor %}

  # Interval (in seconds) for periodic health checks with peers
  {{- "peer_health_check_interval" }} = {{ ic_peer_health_check_interval | default(30) }}

  # Maximum time (in seconds) to wait for peer response before marking unhealthy
  {{- "peer_timeout" }} = {{ ic_peer_timeout | default(10) }}

  # Enable verbose logging for interconnection operations
  {{- "verbose" }} = {{ ic_verbose | default(false) | lower }}

# Logging configuration
[Logging]
  # Log file path (empty = stderr only)
  {{- "file" }} = {{ log_file | default('') }}

  # Log level: info, notice, warning, err, critical, emerg, debug
  {{- "level" }} = {{ log_level }}

  # Syslog facility (e.g., "daemon", "local0")
  {{- "syslog_facility" }} = {{ log_syslog_facility | default('daemon') }}

# Audit logging (optional)
[Audit]
  # Enable audit logging
  {{- "enable" }} = {{ audit_enable | default(false) | lower }}

  # Path to audit log file
  {{- "file" }} = {{ audit_file | default('/var/log/ovn/ovn-ic-db-audit.log') }}

  # Log level for audit events
  {{- "level" }} = {{ audit_level | default('info') }}
